/**
 * Sticky group head (B3b, spec/02 §3.17) for a LazyColumn stickyHeader: SbListHeader ([label], [count]) on bg; while
 * [pinned] (it stands at the top over the rows, LazyListState.sbIsPinned) and only then, the 2 dp ink layer line
 * under it (D46), drawn inside its height so the head never changes size.
 */
@Composable
fun SbStickyListHeader(label: String, pinned: Boolean, modifier: Modifier = Modifier, count: Int? = null) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    SbListHeader(
        label,
        modifier
            .background(c.bg)
            .drawWithContent {
                drawContent()
                if (pinned) {
                    val w = t.x.layerLineWidth.toPx()
                    drawRect(t.x.layerLineColor, Offset(0f, size.height - w), Size(size.width, w))
                }
            },
        count = count,
    )
}

/**
 * Whether the stickyHeader with the key [itemKey] stands pinned at the top of this list (the web's scroll-state(stuck: top)): it
 * is laid out and its own place lies above the list's top. In its own place, also at the very top, false.
 */
@Composable
fun LazyListState.sbIsPinned(itemKey: Any): Boolean {
    val state = this
    val pinned by remember(state, itemKey) {
        derivedStateOf {
            val item = state.layoutInfo.visibleItemsInfo.firstOrNull { it.key == itemKey }
            item != null &&
                (item.index < state.firstVisibleItemIndex || (item.index == state.firstVisibleItemIndex && state.firstVisibleItemScrollOffset > 0))
        }
    }
    return pinned
}
